tool_input.command:
cat > /tmp/test-threshold.mjs << 'EOF'
import { generateReport } from './packages/frai-core/src/eval/index.js';
import { toMarkdown } from './packages/frai-core/src/eval/reporters.js';

const evaluations = [
  {
    id: 'exact_match',
    label: 'Exact Match',
    score: 0.8,
    total: 10,
    matches: 8
  },
  {
    id: 'toxicity',
    label: 'Toxicity',
    score: 0.95,
    total: 10,
    flagged: 0
  }
];

console.log('Test 1: Thresholds that pass');
const report1 = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.7, toxicity: 0.9 }
});
console.log('Report passed:', report1.passed);
console.log('Thresholds:', report1.thresholds);
console.assert(report1.passed === true, 'Expected report to pass');
console.assert(report1.thresholds[0].passed === true, 'exact_match should pass');
console.assert(report1.thresholds[1].passed === true, 'toxicity should pass');

console.log('\nTest 2: Thresholds that fail');
const report2 = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.9, toxicity: 0.9 }
});
console.log('Report passed:', report2.passed);
console.log('Thresholds:', report2.thresholds);
console.assert(report2.passed === false, 'Expected report to fail');
console.assert(report2.thresholds[0].passed === false, 'exact_match should fail');
console.assert(report2.thresholds[1].passed === true, 'toxicity should pass');

console.log('\nTest 3: Metric with null score fails threshold');
const evaluations3 = [
  {
    id: 'exact_match',
    label: 'Exact Match',
    score: null,
    total: 0,
    matches: 0,
    details: 'No data'
  }
];
const report3 = generateReport({
  evaluations: evaluations3,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.9 }
});
console.log('Report passed:', report3.passed);
console.log('Thresholds:', report3.thresholds);
console.assert(report3.passed === false, 'Expected report to fail');
console.assert(report3.thresholds[0].passed === false, 'null score should fail threshold');

console.log('\nTest 4: Markdown includes thresholds');
const markdown = toMarkdown(report1);
console.log('Markdown contains "## Thresholds":', markdown.includes('## Thresholds'));
console.log('Markdown contains "PASS":', markdown.includes('PASS'));
console.assert(markdown.includes('## Thresholds'), 'Should have thresholds section');
console.assert(markdown.includes('PASS'), 'Should show pass status');

console.log('\n✅ All threshold tests passed!');
EOF
node /tmp/test-threshold.mjs
